if(EditorApplication.isPlaying)throw new System.Exception("Edit required");var review=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var room=GameObject.Find("22 ShopWorkflow10 - isolated artistic reconstruction");string Key(Renderer r){var id=GlobalObjectId.GetGlobalObjectIdSlow(r);return id.targetObjectId+":"+id.targetPrefabId;}
var map=review.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>!r.transform.IsChildOf(room.transform)).GroupBy(Key).ToDictionary(g=>g.Key,g=>g.ToArray());var changed=new System.Collections.Generic.List<object>();var baseline=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CM_CrookedMortar_Production02.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);
